import java.io.BufferedReader
import java.io.InputStreamReader
import java.util.StringTokenizer

private const val MOD = 998244353L

private fun multiply(a: Array<LongArray>, b: Array<LongArray>): Array<LongArray> {
    val n = a.size
    val result = Array(n) { LongArray(n) }

    for (i in 0 until n) {
        for (k in 0 until n) {
            val x = a[i][k]
            if (x == 0L) continue
            for (j in 0 until n) {
                val y = b[k][j]
                if (y == 0L) continue
                result[i][j] = (result[i][j] + x * y) % MOD
            }
        }
    }
    return result
}

private fun power(matrix: Array<LongArray>, exponent: Int): Array<LongArray> {
    val n = matrix.size
    var result = Array(n) { i -> LongArray(n) { j -> if (i == j) 1L else 0L } }
    var base = matrix
    var exp = exponent

    while (exp > 0) {
        if ((exp and 1) != 0) result = multiply(result, base)
        base = multiply(base, base)
        exp = exp shr 1
    }
    return result
}

private fun trace(matrix: Array<LongArray>): Long {
    var result = 0L
    for (i in matrix.indices) {
        result += matrix[i][i]
        if (result >= MOD) result -= MOD
    }
    return result
}

fun main() {
    val reader = BufferedReader(InputStreamReader(System.`in`))
    val tokenizer = StringTokenizer(reader.readLine())
    val n = tokenizer.nextToken().toInt()

    val nonMonomer = arrayOf(
        longArrayOf(1L, 0L, 0L),
        longArrayOf(1L, 1L, 0L),
        longArrayOf(1L, 2L, 1L)
    )

    val monomer = arrayOf(
        longArrayOf(0L, 0L, 1L),
        longArrayOf(0L, 0L, 0L),
        longArrayOf(0L, 0L, 0L)
    )

    val fullTransition = Array(12) { LongArray(12) }
    val matchingTransition = Array(4) { LongArray(4) }

    fun addTransition(from: Int, to: Int, weight: Array<LongArray>, allowedWithoutMonomer: Boolean) {
        for (i in 0 until 3) {
            for (j in 0 until 3) {
                val row = from * 3 + i
                val col = to * 3 + j
                fullTransition[row][col] =
                    (fullTransition[row][col] + weight[i][j]) % MOD
            }
        }
        if (allowedWithoutMonomer) {
            matchingTransition[from][to] =
                (matchingTransition[from][to] + 1L) % MOD
        }
    }

    for (state in 0 until 4) {
        val currentOccupied = (state and 1) != 0
        val nextOccupied = (state and 2) != 0
        val shiftedNext = if (nextOccupied) 1 else 0

        if (currentOccupied) {
            addTransition(state, shiftedNext, nonMonomer, true)
        } else {
            addTransition(state, shiftedNext, monomer, false)

            if (!nextOccupied) {
                addTransition(state, 1, nonMonomer, true)
            }

            addTransition(state, shiftedNext or 2, nonMonomer, true)
        }
    }

    val allConfigurations = trace(power(fullTransition, n))
    val noMonomerMatchings = trace(power(matchingTransition, n))

    var answer = (allConfigurations - 3L * noMonomerMatchings % MOD) % MOD
    if (answer < 0L) answer += MOD

    print(answer)
}

