private const val MOD = 998244353L

private fun multiply(a: Array<LongArray>, b: Array<LongArray>): Array<LongArray> {
    val n = a.size
    val result = Array(n) { LongArray(n) }

    for (i in 0 until n) {
        for (k in 0 until n) {
            val x = a[i][k]
            if (x == 0L) continue

            for (j in 0 until n) {
                val y = b[k][j]
                if (y == 0L) continue

                val add = x * y % MOD
                var value = result[i][j] + add
                if (value >= MOD) value -= MOD
                result[i][j] = value
            }
        }
    }
    return result
}

private fun power(matrix: Array<LongArray>, exponent: Int): Array<LongArray> {
    val n = matrix.size
    var base = matrix
    var exp = exponent
    var result = Array(n) { i ->
        LongArray(n).also { it[i] = 1L }
    }

    while (exp > 0) {
        if ((exp and 1) != 0) result = multiply(result, base)
        base = multiply(base, base)
        exp = exp ushr 1
    }
    return result
}

private fun trace(matrix: Array<LongArray>): Long {
    var result = 0L
    for (i in matrix.indices) {
        result += matrix[i][i]
        if (result >= MOD) result -= MOD
    }
    return result
}

