            if (nonDiameter[from][to] != 0L) {
                for (i in 0 until 3) {
                    for (j in 0 until 3) {
                        transfer[from * 3 + i][to * 3 + j] =
                            (transfer[from * 3 + i][to * 3 + j] + advance[i][j]) % MOD
