import java.io.BufferedReader
import java.io.InputStreamReader

private const val MOD = 998244353L

private fun norm(x: Long): Long {
    val r = x % MOD
    return if (r < 0) r + MOD else r
}

private fun trim(a: LongArray): LongArray {
    var size = a.size
    while (size > 1 && a[size - 1] == 0L) size--
    return a.copyOf(size)
}

private fun add(a: LongArray, b: LongArray): LongArray {
    val result = LongArray(maxOf(a.size, b.size))
    for (i in result.indices) {
        val x = if (i < a.size) a[i] else 0L
        val y = if (i < b.size) b[i] else 0L
        result[i] = (x + y) % MOD
    }
    return trim(result)
}

private fun subtract(a: LongArray, b: LongArray): LongArray {
    val result = LongArray(maxOf(a.size, b.size))
    for (i in result.indices) {
        val x = if (i < a.size) a[i] else 0L
        val y = if (i < b.size) b[i] else 0L
        result[i] = norm(x - y)
    }
    return trim(result)
}

private fun scale(a: LongArray, multiplier: Long): LongArray {
    val m = norm(multiplier)
    val result = LongArray(a.size)
    for (i in a.indices) {
        result[i] = a[i] * m % MOD
    }
    return trim(result)
}

private fun multiply(a: LongArray, b: LongArray): LongArray {
    val result = LongArray(a.size + b.size - 1)
    for (i in a.indices) {
        if (a[i] == 0L) continue
        for (j in b.indices) {
            if (b[j] == 0L) continue
            result[i + j] = (result[i + j] + a[i] * b[j]) % MOD
        }
    }
    return trim(result)
}

private fun derivative(a: LongArray): LongArray {
    if (a.size <= 1) return longArrayOf(0L)
    val result = LongArray(a.size - 1)
    for (i in 1 until a.size) {
        result[i - 1] = a[i] * i.toLong() % MOD
    }
    return trim(result)
}

private fun shift(a: LongArray, positions: Int): LongArray {
    if (a.size == 1 && a[0] == 0L) return longArrayOf(0L)
    val result = LongArray(a.size + positions)
    for (i in a.indices) result[i + positions] = a[i]
    return result
}

private fun logarithmicDerivativeCoefficient(p: LongArray, n: Int): Long {
    val numerator = shift(derivative(p), 1)
    val quotient = LongArray(n + 1)

    for (i in 0..n) {
        var value = if (i < numerator.size) numerator[i] else 0L
        val limit = minOf(i, p.size - 1)
        for (j in 1..limit) {
            value -= p[j] * quotient[i - j] % MOD
            if (value < 0) value += MOD
        }
        quotient[i] = value
    }
    return quotient[n]
}

fun main() {
    val reader = BufferedReader(InputStreamReader(System.`in`))
    val n = reader.readLine().trim().toInt()

    val s = longArrayOf(1L, 0L, MOD - 1L, 0L, MOD - 1L)
    val sDerivative = derivative(s)
    val sSquared = multiply(s, s)
    val sCubed = multiply(sSquared, s)

    val r = scale(shift(sDerivative, 1), -1L)

    val firstPart = multiply(derivative(r), s)
    val secondPart = scale(multiply(r, sDerivative), 2L)
    val thetaSquaredNumerator = shift(subtract(firstPart, secondPart), 1)

    fun numerator(c: Long, extraShift: Int): LongArray {
        var result = thetaSquaredNumerator
        result = add(result, scale(multiply(r, s), 2L * c))
        result = add(result, scale(sSquared, c * c))
        return shift(result, extraShift)
    }

    val n0 = numerator(0L, 1)
    val n1 = numerator(1L, 2)
    val n2 = numerator(2L, 3)

    val left = subtract(sCubed, n0)
    val right = subtract(sCubed, n2)
    val p = subtract(multiply(left, right), multiply(n1, n1))

    val coefficientS = logarithmicDerivativeCoefficient(s, n)
    val coefficientP = logarithmicDerivativeCoefficient(p, n)

    val answer = norm(6L * coefficientS - coefficientP)
    println(answer)
}

import java.io.BufferedReader
