private const val MOD = 998244353L

private fun convolution(a: LongArray, b: LongArray): LongArray {
    val result = LongArray(a.size + b.size - 1)
    for (i in a.indices) {
        if (a[i] == 0L) continue
        for (j in b.indices) {
            if (b[j] == 0L) continue
            result[i + j] = (result[i + j] + a[i] * b[j]) % MOD
        }
    }
    return trim(result)
}

private fun trim(a: LongArray): LongArray {
    var last = a.size - 1
    while (last > 0 && a[last] == 0L) last--
    return a.copyOf(last + 1)
}

private fun subtract(a: LongArray, b: LongArray): LongArray {
    val size = maxOf(a.size, b.size)
    val result = LongArray(size)
    for (i in 0 until size) {
        val x = if (i < a.size) a[i] else 0L
        val y = if (i < b.size) b[i] else 0L
        result[i] = (x - y + MOD) % MOD
    }
    return trim(result)
}

private fun logCoefficient(poly: LongArray, n: Int, inv: LongArray): Long {
    val coefficients = LongArray(n + 1)

    for (k in 1..n) {
        var sum = 0L
        val maxDegree = minOf(poly.size - 1, k - 1)

        for (degree in 1..maxDegree) {
            val i = k - degree
            val term = (i.toLong() * coefficients[i]) % MOD
            sum = (sum + term * poly[degree]) % MOD
        }

        val ak = if (k < poly.size) poly[k] else 0L
        coefficients[k] = (ak - sum * inv[k] % MOD + MOD) % MOD
    }

    return coefficients[n]
}

fun main() {
    val reader = BufferedReader(InputStreamReader(System.`in`))
    val n = StringTokenizer(reader.readLine()).nextToken().toInt()

    val inverses = LongArray(n + 1)
    inverses[1] = 1L
    for (i in 2..n) {
        inverses[i] = (MOD - (MOD / i) * inverses[(MOD % i).toInt()] % MOD) % MOD
    }

    val q = longArrayOf(1L, 0L, MOD - 1, 0L, MOD - 1)
    val denominator = convolution(convolution(q, q), q)

    val limit = 80
    val f = LongArray(limit + 1)
    f[0] = 1L
    for (i in 1..limit) {
        var value = 0L
        if (i >= 2) value += f[i - 2]
        if (i >= 4) value += f[i - 4]
        f[i] = value % MOD
    }

    val numerators = Array(3) { LongArray(1) }

    for (stateSum in 0..2) {
        val series = LongArray(limit + 1)

        for (m in 0..limit) {
            val degree = m + stateSum + 1
            if (degree > limit) break

            val x = (m + stateSum).toLong()
            val weight = x * x % MOD
            series[degree] = weight * f[m] % MOD
        }

        val product = convolution(series, denominator)
        val bounded = if (product.size > limit + 1) {
            product.copyOf(limit + 1)
        } else {
            product
        }
        numerators[stateSum] = trim(bounded)
    }

    val left = subtract(denominator, numerators[0])
    val right = subtract(denominator, numerators[2])

    val determinantNumerator = subtract(
        convolution(left, right),
        convolution(numerators[1], numerators[1])
    )

    val logDenominator = logCoefficient(denominator, n, inverses)
    val logNumerator = logCoefficient(determinantNumerator, n, inverses)

    val coefficient = (2L * logDenominator - logNumerator + MOD) % MOD
    val answer = n.toLong() * coefficient % MOD

    print(answer)
}

